import{_ as a,c,o as t,a3 as o}from"./chunks/framework.czLORLkK.js";const h=JSON.parse('{"title":"SyncAPIM 엔터프라이즈 도입 FAQ","description":"SyncAPIM 도입 시 자주 묻는 질문(4-JVM 프로세스 분리 이유, OpenSearch 없는 PostgreSQL 18.6 단일 스토리지 성능, 기존 시스템 무중단 연동, 온프레미스 폐쇄망 지원)에 대한 답변입니다.","frontmatter":{"title":"SyncAPIM 엔터프라이즈 도입 FAQ","sidebarTitle":"도입 FAQ","description":"SyncAPIM 도입 시 자주 묻는 질문(4-JVM 프로세스 분리 이유, OpenSearch 없는 PostgreSQL 18.6 단일 스토리지 성능, 기존 시스템 무중단 연동, 온프레미스 폐쇄망 지원)에 대한 답변입니다.","head":[["meta",{"name":"keywords","content":"SyncAPIM FAQ, API 보안 도입, 4-JVM, PostgreSQL 18.6, 온프레미스 WAF, 섀도우 API"}],["meta",{"property":"og:title","content":"SyncAPIM 엔터프라이즈 도입 FAQ"}],["meta",{"property":"og:description","content":"SyncAPIM 아키텍처, 성능 격리, 스토리지 단일화 및 기존 서비스 연동에 관한 자주 묻는 질문"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/syncapim/enterprise-faq"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/syncapim/enterprise-faq"}]],"sort":5},"headers":[],"relativePath":"syncapim/enterprise-faq.md","filePath":"ko/syncapim/enterprise-faq.md","lastUpdated":1794045358000}'),r={name:"syncapim/enterprise-faq.md"};function n(d,e,i,s,p,m){return t(),c("div",null,[...e[0]||(e[0]=[o('<h1 id="syncapim-엔터프라이즈-도입-faq" tabindex="-1">SyncAPIM 엔터프라이즈 도입 FAQ <a class="header-anchor" href="#syncapim-엔터프라이즈-도입-faq" aria-label="Permalink to “SyncAPIM 엔터프라이즈 도입 FAQ”">​</a></h1><h3 id="q1-왜-단일-서버가-아닌-4개의-개별-jvm-admin-receiver-detector-gateway-으로-분리되어-있나요" tabindex="-1">Q1. 왜 단일 서버가 아닌 4개의 개별 JVM(<code>admin</code>, <code>receiver</code>, <code>detector</code>, <code>gateway</code>)으로 분리되어 있나요? <a class="header-anchor" href="#q1-왜-단일-서버가-아닌-4개의-개별-jvm-admin-receiver-detector-gateway-으로-분리되어-있나요" aria-label="Permalink to “Q1. 왜 단일 서버가 아닌 4개의 개별 JVM(admin, receiver, detector, gateway)으로 분리되어 있나요?”">​</a></h3><p>API 보안 관제 솔루션은 초당 수천 건 이상의 네트워크 패킷을 수신(<code>receiver</code>)하고, 다수의 정규식과 JSON 스키마 추론(<code>detector</code>)을 수행해야 합니다. 만약 패킷 수신·탐지 엔진과 관리자 UI 백엔드(<code>admin</code>) 또는 인라인 게이트웨이(<code>gateway</code>)가 동일한 JVM 힙과 CPU 스레드 풀을 공유하면, 대량 공격 트래픽 유입 시 관리 콘솔 응답이 멈추거나 게이트웨이 지연이 발생할 수 있습니다. 따라서 <code>SyncAPIM</code>은 <strong>공통 도메인 모듈(<code>sync-apim-common</code>)은 공유하되 런타임 프로세스는 4개 JVM으로 분리</strong>하여 각 구간의 성능을 독립적으로 보장하고 개별 스케일아웃(Scale-Out)이 가능하도록 설계되었습니다.</p><h3 id="q2-별도의-무거운-opensearch-elasticsearch-클러스터-없이-대용량-패킷-로그-검색이-가능한가요" tabindex="-1">Q2. 별도의 무거운 OpenSearch/Elasticsearch 클러스터 없이 대용량 패킷 로그 검색이 가능한가요? <a class="header-anchor" href="#q2-별도의-무거운-opensearch-elasticsearch-클러스터-없이-대용량-패킷-로그-검색이-가능한가요" aria-label="Permalink to “Q2. 별도의 무거운 OpenSearch/Elasticsearch 클러스터 없이 대용량 패킷 로그 검색이 가능한가요?”">​</a></h3><p>네, 가능합니다. 기존 레거시 환경에서는 패킷 이벤트를 위해 별도의 OpenSearch 클러스터(최소 수 GB~수십 GB JVM 힙 필요)를 중복 운영해야 했으나, <code>SyncAPIM</code>은 <strong>PostgreSQL 18.6의 <code>JSONB</code> 컬럼과 <code>pg_trgm</code> GIN 인덱스</strong>를 결합한 <code>wapf_detect_event</code> 단일 테이블 구조를 채택했습니다. 이를 통해 공격 페이로드 부분 문자열 검색, 위협 코드 필터링, 시계열 집계를 단일 RDBMS 위에서 빠르게 처리하면서도 인프라 구축·유지보수 비용을 크게 절감합니다.</p><h3 id="q3-운영-중인-기존-레거시-was나-마이크로서비스를-수정하지-않고도-적용할-수-있나요" tabindex="-1">Q3. 운영 중인 기존 레거시 WAS나 마이크로서비스를 수정하지 않고도 적용할 수 있나요? <a class="header-anchor" href="#q3-운영-중인-기존-레거시-was나-마이크로서비스를-수정하지-않고도-적용할-수-있나요" aria-label="Permalink to “Q3. 운영 중인 기존 레거시 WAS나 마이크로서비스를 수정하지 않고도 적용할 수 있나요?”">​</a></h3><p>네, 두 가지 무중단 방식을 모두 지원합니다:</p><ol><li><strong>비침투 미러링 모드 (Out-of-Band)</strong>: 보호 대상 서버의 네트워크 인터페이스에 경량 수집 에이전트(Packetbeat/Filebeat)를 설치하거나 앞단 로드밸런서에서 <code>sync-apim-receiver</code>(TCP <code>5044</code>/<code>5055</code> 또는 HTTP <code>18090</code>)로 트래픽을 미러링하면, 운영 서비스에 지연 영향(Latency Impact 0ms) 없이 섀도우 API 발견과 위협 탐지를 즉시 시작할 수 있습니다.</li><li><strong>인라인 차단 게이트웨이 모드 (In-Line)</strong>: 고위험 엔드포인트의 실시간 차단(<code>403 Forbidden</code>)이 필요한 경우 <code>sync-apim-gateway</code>(<code>18091</code>)를 앞단에 배치하여 관리 콘솔에서 원클릭으로 차단 정책을 즉시 집행할 수 있습니다.</li></ol><h3 id="q4-외부-인터넷이-완전히-차단된-폐쇄망-air-gapped-환경에서도-ai-보안-분석이-동작하나요" tabindex="-1">Q4. 외부 인터넷이 완전히 차단된 폐쇄망(Air-Gapped) 환경에서도 AI 보안 분석이 동작하나요? <a class="header-anchor" href="#q4-외부-인터넷이-완전히-차단된-폐쇄망-air-gapped-환경에서도-ai-보안-분석이-동작하나요" aria-label="Permalink to “Q4. 외부 인터넷이 완전히 차단된 폐쇄망(Air-Gapped) 환경에서도 AI 보안 분석이 동작하나요?”">​</a></h3><p>네, 동작합니다. <code>SyncAPIM</code>의 핵심 패킷 수집, OpenAPI 3.0.1 스펙 추론, Contract Drift 비교 감사, 6대 WAF 정규식/JWT 위협 탐지 및 8대 PII 마스킹 엔진은 외부 LLM 연결 없이도 <strong>결정론적(Deterministic) 알고리즘으로 100% 자체 동작</strong>합니다. 또한 위협 포렌식 요약 브리핑은 사내 구축형 <code>SyncLLM</code>(vLLM/Ollama 연동)을 통해 폐쇄망 내부에서 안전하게 생성됩니다.</p>',10)])])}const y=a(r,[["render",n]]);export{h as __pageData,y as default};
